microbenchmark.caller_source:
//! Disposable benchmark of existing continuation entry at several arities.
#[path = "../tests/support/oop.rs"]
mod oop;
use birnam_abi::size;
unsafe extern "C" { fn clock_gettime_nsec_np(clock: u32) -> u64; }
fn main() {
    let h = oop::bootstrap();
    let q = h.scope();
    let fixture = h.load_native(&q, &std::path::PathBuf::from(std::env::args().nth(1).unwrap()), &[]).unwrap();
    let selector = q.keep(h.intern(b"probe").unwrap()).unwrap();
    let method = q.call(fixture, b"methodAt:", &[selector]).unwrap();
    let receiver = q.call(h.named(b"Object").unwrap(), b"clone", &[]).unwrap();
    let vt = q.call(h.id.root, b"ensurePrivateVtableFor:", &[receiver]).unwrap();
    q.call(vt, b"addMethod", &[selector, method]).unwrap();
    let gc = h.named(b"GC").unwrap();
    q.call(gc, b"automaticCollection:", &[size(0).unwrap()]).unwrap();
    for arity in [0, 1, 8, 64] {
        let args: Vec<_> = (1..=arity).map(|i| size(i).unwrap()).collect();
        let expected = args.last().copied().unwrap_or(receiver);
        for _ in 0..100 { assert_eq!(unsafe { h.id.send(receiver, selector, &args).unwrap() }, expected); }
        for _ in 0..7 {
            q.call(gc, b"collectPrecisely", &[]).unwrap();
            let start = unsafe { clock_gettime_nsec_np(16) };
            for _ in 0..10000 { assert_eq!(unsafe { h.id.send(receiver, selector, &args).unwrap() }, expected); }
            println!("{arity} {}", unsafe { clock_gettime_nsec_np(16) } - start);
        }
    }
}

